using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();
        if (statusFilter.HasValue)
            query = query.Where(s => s.Status == (int)statusFilter.Value);

        return await query.Select(s => MapToDto(s)).ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : MapToDto(entity);
    }

    public async Task<ShipmentDto?> GetShipmentByIdAsync(int id)
    {
        var entity = await db.Shipments.FindAsync(id);
        return entity is null ? null : MapToDto(entity);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var entity = new Shipment
        {
            TrackingNumber = $"ST-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpper()}",
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = (int)shipment.Status,
            ShippedDate = shipment.ShippedDate,
            EstimatedDelivery = shipment.EstimatedDelivery,
            ActualDelivery = shipment.ActualDelivery,
            RecipientName = shipment.RecipientName,
            SenderName = shipment.SenderName,
            Notes = shipment.Notes
        };

        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return MapToDto(entity);
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentUpdateDto update)
    {
        var entity = await db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException("Shipment not found");

        entity.Status = (int)update.Status;
        if (update.Notes is not null)
            entity.Notes = update.Notes;
        if (update.Status == ShipmentStatus.Delivered)
            entity.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        SenderName = s.SenderName,
        Notes = s.Notes
    };
}

