                <select class="form-select" @bind="newStatus">
                    @foreach (var s in Enum.GetValues<ShipmentStatus>())
                    {
                        <option value="@s">@s</option>
                    }
                </select>
            </div>
            <div class="mb-3">
                <label class="form-label">Notes (optional)</label>
                <textarea class="form-control" @bind="updateNotes" rows="3"></textarea>
            </div>
            <button class="btn btn-primary" @onclick="UpdateStatus" disabled="@updating">
                @(updating ? "Updating..." : "Update Status")
            </button>
            @if (updateMessage is not null)
            {
                <div class="alert alert-success mt-2">@updateMessage</div>
            }
        </div>
