@code {
    [Parameter] public int Id { get; set; }

    private ShipmentDto? shipment;
    private ShipmentStatus newStatus;
    private string? updateNotes;
    private bool updating;
    private string? updateMessage;

    protected override async Task OnInitializedAsync()
    {
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        if (shipment is not null)
            newStatus = shipment.Status;
    }

    private async Task UpdateStatus()
    {
        updating = true;
        updateMessage = null;
        try
        {
            await ShipmentService.UpdateShipmentStatusAsync(Id, new ShipmentUpdateDto
            {
                Status = newStatus,
                Notes = updateNotes
            });
            shipment = await ShipmentService.GetShipmentByIdAsync(Id);
            updateMessage = "Status updated successfully.";
        }
        finally
        {
            updating = false;
        }
    }
}

@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]

@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number"
                   @bind="searchTracking" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search">Track</button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">Shipment not found. Please check your tracking number.</div>
}
else if (shipment is not null)
{
    <div class="card mb-4">
        <div class="card-body">
            <h4 class="card-title">@shipment.TrackingNumber</h4>

            <!-- Status progress indicator -->
            <div class="d-flex justify-content-between my-4 position-relative">
                @{
                    var steps = new[] {
                        ShipmentStatus.Pending,
                        ShipmentStatus.PickedUp,
                        ShipmentStatus.InTransit,
                        ShipmentStatus.OutForDelivery,
                        ShipmentStatus.Delivered
                    };
                    var currentIndex = Array.IndexOf(steps, shipment.Status);
                    var isSpecial = shipment.Status == ShipmentStatus.Delayed || shipment.Status == ShipmentStatus.Returned;
                }
                @foreach (var (step, i) in steps.Select((s, i) => (s, i)))
                {
                    var isActive = !isSpecial && i <= currentIndex;
                    <div class="text-center flex-fill">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light border")"
                             style="width:40px;height:40px;">
                            @(i + 1)
                        </div>
                        <div class="small mt-1">@step</div>
                    </div>
                }
            </div>

            @if (isSpecial)
            {
                <div class="alert @(shipment.Status == ShipmentStatus.Delayed ? "alert-danger" : "alert-dark")">
                    Status: <strong>@shipment.Status</strong>
                    @if (!string.IsNullOrEmpty(shipment.Notes))
                    {
                        <span> — @shipment.Notes</span>
                    }
                </div>
            }

            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt><dd>@shipment.Origin</dd>
                        <dt>Destination</dt><dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt><dd>@shipment.ShippedDate.ToShortDateString()</dd>
                        <dt>Estimated Delivery</dt><dd>@(shipment.EstimatedDelivery?.ToShortDateString() ?? "—")</dd>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt><dd>@shipment.ActualDelivery.Value.ToShortDateString()</dd>
                        }
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string searchTracking = string.Empty;
    private ShipmentDto? shipment;
    private bool searched;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchTracking = TrackingNumber;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(searchTracking)) return;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchTracking.Trim());
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }
}

@page "/shipments/create"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]

@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Create Shipment</PageTitle>

<h2>Create New Shipment</h2>

<div class="row">
    <div class="col-md-6">
        <EditForm Model="shipment" OnValidSubmit="HandleSubmit" FormName="createShipment">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label class="form-label">Origin</label>
                <InputText class="form-control" @bind-Value="shipment.Origin" />
            </div>

            <div class="mb-3">
                <label class="form-label">Destination</label>
                <InputText class="form-control" @bind-Value="shipment.Destination" />
            </div>

            <div class="mb-3">
                <label class="form-label">Sender Name</label>
                <InputText class="form-control" @bind-Value="shipment.SenderName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Recipient Name</label>
                <InputText class="form-control" @bind-Value="shipment.RecipientName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Shipped Date</label>
                <InputDate class="form-control" @bind-Value="shipment.ShippedDate" />
            </div>

            <div class="mb-3">
                <label class="form-label">Estimated Delivery</label>
                <InputDate class="form-control" @bind-Value="shipment.EstimatedDelivery" />
            </div>

            <div class="mb-3">
                <label class="form-label">Notes</label>
                <InputTextArea class="form-control" @bind-Value="shipment.Notes" rows="3" />
            </div>

            <button type="submit" class="btn btn-primary" disabled="@submitting">
                @(submitting ? "Creating..." : "Create Shipment")
            </button>
            <a href="/shipments" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
</div>

@code {
    private ShipmentDto shipment = new() { ShippedDate = DateTime.Today };
    private bool submitting;

    private async Task HandleSubmit()
    {
        submitting = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(shipment);
            Navigation.NavigateTo("/shipments");
        }
        finally
        {
            submitting = false;
        }
    }
}

