 @page "/shipments"
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @attribute [Authorize(Roles = "Dispatcher")]

 @inject IShipmentService ShipmentService
 @inject NavigationManager Navigation

 <PageTitle>Shipments</PageTitle>

 <h2>Shipments</h2>

 <div class="d-flex justify-content-between align-items-center mb-3">
     <div>
         <label class="form-label me-2">Filter by status:</label>
         <select class="form-select d-inline-block w-auto" @onchange="OnFilterChanged">
             <option value="">All</option>
             @foreach (var status in Enum.GetValues<ShipmentStatus>())
             {
                 <option value="@status">@status</option>
             }
         </select>
     </div>
     <a class="btn btn-primary" href="/shipments/create">New Shipment</a>
 </div>

 @if (shipments is null)
 {
     <p><em>Loading...</em></p>
 }
 else if (shipments.Count == 0)
 {
     <p>No shipments found.</p>
 }
 else
 {
     <table class="table table-striped table-hover">
         <thead>
             <tr>
                 <th>Tracking #</th>
                 <th>Origin</th>
                 <th>Destination</th>
                 <th>Status</th>
                 <th>Shipped Date</th>
                 <th>Est. Delivery</th>
             </tr>
         </thead>
         <tbody>
             @foreach (var s in shipments)
             {
                 <tr style="cursor:pointer" @onclick="() => GoToShipment(s.Id)">
                     <td>@s.TrackingNumber</td>
                     <td>@s.Origin</td>
                     <td>@s.Destination</td>
                     <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
                     <td>@s.ShippedDate.ToShortDateString()</td>
                     <td>@(s.EstimatedDelivery?.ToShortDateString() ?? "—")</td>
                 </tr>
             }
         </tbody>
     </table>
 }

 @code {
     private List<ShipmentDto>? shipments;
     private ShipmentStatus? currentFilter;

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         shipments = await ShipmentService.GetShipmentsAsync(currentFilter);
     }

     private async Task OnFilterChanged(ChangeEventArgs e)
     {
         currentFilter = string.IsNullOrEmpty(e.Value?.ToString())
             ? null
             : Enum.Parse<ShipmentStatus>(e.Value.ToString()!);
         await LoadShipments();
     }

     private static string GetStatusColor(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "secondary",
         ShipmentStatus.PickedUp => "info",
         ShipmentStatus.InTransit => "primary",
         ShipmentStatus.OutForDelivery => "warning",
         ShipmentStatus.Delivered => "success",
         ShipmentStatus.Delayed => "danger",
         ShipmentStatus.Returned => "dark",
         _ => "secondary"
     };

     private void GoToShipment(int id)
     {
         Navigation.NavigateTo($"/shipments/{id}");
     }
 }

